243	    /**
244	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
245	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
246	     * Validation already rejects {@code null} values and the pattern-constrained fields
247	     * when blank, but {@code address} and {@code city} have no pattern, so a
248	     * whitespace-only value would otherwise slip through.
249	     *
250	     * @param ownerFieldsDto the submitted owner fields
251	     * @throws RequiredFieldsMissingException if any required field is missing or blank
252	     */
253	    /**
254	     * Common street-type abbreviations expanded during address normalization. Keys are the
255	     * upper-cased abbreviation tokens; values are their canonical expansions.
256	     */
257	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
258	        "ST", "STREET",
259	        "RD", "ROAD",
260	        "AVE", "AVENUE");
261	
262	    /**
263	     * Normalizes the submitted address on create, accepting either the structured form
264	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
265	     * form retained for backward compatibility. Each supplied field is canonicalized the same way
266	     * (trimmed, internal whitespace collapsed to a single space, upper-cased, and common
267	     * street-type abbreviations expanded — see {@link #ADDRESS_ABBREVIATIONS}), and the normalized
268	     * values are written back onto the request.
269	     *
270	     * <p>The structured fields are preferred when present: when a non-blank {@code addressLine1} is
271	     * supplied, the flat {@code address} is set to the composed value — the normalized
272	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended
273	     * when an {@code addressLine2} is present — otherwise it keeps the normalized flat value. The
274	     * composed {@code address} is therefore persisted, echoed back, and used by everything that
275	     * reads the flat address. A blank/absent value in every form leaves {@code address} blank so the
276	     * required-field check can report it as missing.
277	     *
278	     * @param ownerFieldsDto the submitted owner fields
279	     */
280	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
281	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
282	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
283	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
284	        ownerFieldsDto.setAddressLine1(addressLine1);
285	        ownerFieldsDto.setAddressLine2(addressLine2);
286	        String composed;
287	        if (addressLine1 != null && !addressLine1.isBlank()) {
288	            composed = (addressLine2 != null && !addressLine2.isBlank())
289	                ? addressLine1 + " " + addressLine2
290	                : addressLine1;
291	        }
292	        else {
293	            composed = flat;
294	        }
295	        ownerFieldsDto.setAddress(composed);
296	    }
297	
298	    /**
299	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
300	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
301	     * expanded to its full form. A {@code null} value is returned unchanged.
302	     *
303	     * @param raw the address to canonicalize, possibly {@code null}
304	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
305	     */
306	    private static String normalizeAddress(String raw) {
307	        if (raw == null) {
308	            return null;
309	        }
310	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
311	        if (collapsed.isEmpty()) {
312	            return collapsed;
313	        }
314	        String[] tokens = collapsed.split(" ");
315	        StringBuilder sb = new StringBuilder(collapsed.length());
316	        for (int i = 0; i < tokens.length; i++) {
317	            if (i > 0) {
318	                sb.append(' ');
319	            }
320	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
321	        }
322	        return sb.toString();
323	    }
324	
325	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
326	        List<String> errors = new ArrayList<>();
327	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
328	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
329	        requireText("address", ownerFieldsDto.getAddress(), errors);
330	        requireText("city", ownerFieldsDto.getCity(), errors);
331	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
332	        if (!errors.isEmpty()) {
333	            throw new RequiredFieldsMissingException(errors);
334	        }
335	    }
336	
337	    private static void requireText(String field, String value, List<String> errors) {
338	        if (value == null || value.isBlank()) {
339	            errors.add(field);
340	        }
341	    }
342	
343	    /**
344	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
345	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
346	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
347	     */
348	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
349	        "NSW", new int[] {2000, 2099},
350	        "VIC", new int[] {3000, 3099},
351	        "QLD", new int[] {4000, 4099});
352	
353	    /**
354	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
355	     * {@code null} value is accepted. When present it has already been constrained to four digits
356	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
357	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
358	     * the postcode must fall within that region's inclusive range
359	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
360	     *
361	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
362	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
363	     *                                  city's region
364	     */
365	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
366	        String postcode = ownerFieldsDto.getPostcode();
367	        if (postcode == null) {
368	            return;
369	        }
370	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
371	            .regionFor(ownerFieldsDto.getCity());
372	        int[] range = REGION_POSTCODE_RANGE.get(region);
373	        if (range == null) {
374	            return;
375	        }
376	        int value = Integer.parseInt(postcode);
377	        if (value < range[0] || value > range[1]) {
378	            throw new InvalidPostcodeException(postcode);
379	        }
380	    }
381	
382	    /**
383	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
384	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
385	     * and echoed back in that form.
386	     *
387	     * @param ownerFieldsDto the submitted owner fields
388	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
389	     *                                        valid E.164 number
390	     */
391	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
392	        String e164 = toE164(ownerFieldsDto.getTelephone());
393	        if (e164 == null) {
394	            throw new RequiredFieldsMissingException(List.of("telephone"));
395	        }
396	        ownerFieldsDto.setTelephone(e164);
397	    }
398	
399	    /**
400	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
401	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
402	     * and country code are present they are kept; otherwise country code {@code '+61'} is
403	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
404	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
405	     * the national-number length must match the country: {@code '+61'} (Australia) requires
406	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
407	     *
408	     * @param raw the submitted telephone, possibly {@code null}
409	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
410	     */
411	    private static String toE164(String raw) {
412	        if (raw == null) {
413	            return null;
414	        }
415	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
416	        String digits;
417	        if (cleaned.startsWith("+")) {
418	            digits = cleaned.substring(1);
419	        } else {
420	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
421	            digits = "61" + national;
422	        }
423	        if (!digits.matches("[0-9]{8,15}")) {
424	            return null;
425	        }
426	        if (digits.startsWith("61")) {
427	            // Australia: exactly 9 national digits after the '+61' country code.
428	            if (digits.length() - 2 != 9) {
429	                return null;
430	            }
431	        } else if (digits.startsWith("1")) {
432	            // NANP: exactly 10 national digits after the '+1' country code.
433	            if (digits.length() - 1 != 10) {
434	                return null;
435	            }
436	        }
437	        return "+" + digits;
438	    }
439	
440	    /**
441	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
442	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
443	     * each stored owner's telephone is normalized the same way before comparison so differing
444	     * input formats collapse to the same value.
445	     *
446	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
447	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
448	     *                                     same E.164 telephone
449	     */
450	    /**
451	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
452	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
453	     * the parts may contain whitespace or a second {@code @}.
454	     */
455	    private static final Pattern EMAIL_PATTERN =
456	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
457	
458	    /**
459	     * Disposable email domains that are not accepted for an owner's email. A create whose email
460	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
461	     * rejected. Kept lower-cased to match the normalized email.
462	     */
463	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
464	        "mailinator.com",
465	        "tempmail.com",
466	        "guerrillamail.com");
467	
468	    /**
469	     * Normalizes the submitted email when present: the value is trimmed, required to be a
470	     * syntactically valid address, required not to use a disposable-email domain, and written back
471	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
472	     * left untouched — the field is optional.
473	     *
474	     * @param ownerFieldsDto the submitted owner fields
475	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
476	     *                               valid, or its domain is on the disposable-domain blocklist
477	     */
478	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
479	        String email = ownerFieldsDto.getEmail();
480	        if (email == null) {
481	            return;
482	        }
483	        String trimmed = email.strip();
484	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
485	            throw new InvalidEmailException(email);
486	        }
487	        String normalized = trimmed.toLowerCase(Locale.ROOT);
488	        String domain = normalized.substring(normalized.indexOf('@') + 1);
489	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
490	            throw new InvalidEmailException(email);
491	        }
492	        ownerFieldsDto.setEmail(normalized);
493	    }
494	
495	    /**
496	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
497	     * date. A registration may be back-dated but never post-dated. The check is made against the
498	     * value as supplied, before any defaulting or business-day roll (see
499	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
500	     * to the server date).
501	     *
502	     * @param ownerFieldsDto the submitted owner fields
503	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
504	     *                                         after the server's current date
505	     */
506	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
507	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
508	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
509	            throw new FutureRegistrationDateException(supplied);
510	        }
511	    }
512	
513	    /**
514	     * Establishes the effective registration date on create and rolls it onto a business day.
515	     * When the client does not supply a {@code registrationDate} it defaults to the server's
516	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
517	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
518	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
519	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
520	     * the membership number's year segment and the daily create-limit).
521	     *
522	     * @param ownerFieldsDto the submitted owner fields
523	     */
524	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
525	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
526	        if (effective == null) {
527	            effective = LocalDate.now();
528	        }
529	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
530	    }
531	
532	    /**
533	     * Fixed public holidays that the business-day roll skips. A registration date that lands on
534	     * one of these dates is advanced to the next non-holiday business day (see
535	     * {@link #toBusinessDay}).
536	     */
537	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
538	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
539	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
540	        LocalDate.parse("2026-12-28"));
541	
542	    /**
543	     * Rolls a date forward to the next business day: any date that falls on a Saturday, a Sunday
544	     * or a listed public holiday is advanced one day at a time until it lands on a weekday that is
545	     * not a public holiday; any other date is returned unchanged.
546	     *
547	     * @param date the date to adjust
548	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday
549	     *         business day
550	     */
551	    private static LocalDate toBusinessDay(LocalDate date) {
552	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
553	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
554	            || PUBLIC_HOLIDAYS.contains(date)) {
555	            date = date.plusDays(1);
556	        }
557	        return date;
558	    }
559	
560	    /**
561	     * Assigns the owner's {@code customerCode} on create, formatted
562	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
563	     * (preferring the postcode range, falling back to the city — the same derivation that yields
564	     * the owner's {@code locality}, see
565	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
566	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
567	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
568	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
569	     * customer code only when their normalized telephone and last name both match.
570	     *
571	     * <p>When the computed customer code collides with an existing owner's {@code customerCode},
572	     * it is de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
573	     * makes it unique among the existing owners, so distinct owners always receive distinct codes.
574	     *
575	     * @param owner the owner being created (with its {@code postcode}, {@code city},
576	     *              {@code telephone} and {@code lastName} already set)
577	     */
578	    private void assignCustomerCode(Owner owner) {
579	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
580	            .regionFor(owner.getPostcode(), owner.getCity());
581	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
582	            .substring(0, 8).toUpperCase(Locale.ROOT);
583	        String base = region + "-" + hash8;
584	        Set<String> existing = this.clinicService.findAllOwners().stream()
585	            .map(Owner::getCustomerCode)
586	            .filter(Objects::nonNull)
587	            .collect(Collectors.toSet());
588	        String customerCode = base;
589	        for (int n = 2; existing.contains(customerCode); n++) {
590	            customerCode = base + "-" + n;
591	        }
592	        owner.setCustomerCode(customerCode);
593	    }
594	
595	    /**
596	     * Assigns the owner's {@code householdId} on create: a stable, deterministic identifier for
597	     * the household, the first 12 hex characters of the SHA-256 digest of the owner's normalized
598	     * {@code lastName} and {@code postcode} (see {@link #householdIdFor}). Because it is derived
599	     * purely from those two fields, every owner sharing a last name and postcode is assigned the
600	     * same value automatically — including one joining an existing household via
601	     * {@code sharesHousehold} — independent of create order.
602	     *
603	     * @param owner the owner being created (with its {@code lastName} and {@code postcode} already set)
604	     */
605	    private void assignHouseholdId(Owner owner) {
606	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
607	    }
608	
609	    /**
610	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
611	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
612	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
613	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
614	     * every owner sharing a last name and postcode receives the same value, independent of create
615	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #identityKeyFor}
616	     * (which folds it into the identity key for duplicate detection) and
617	     * {@link #rejectDuplicateHousehold} (which blocks a second owner in the same household).
618	     *
619	     * @param lastName the owner's last name
620	     * @param postcode the owner's postcode, possibly {@code null}
621	     * @return the derived household id
622	     */
623	    private static String householdIdFor(String lastName, String postcode) {
624	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
625	        return sha256Hex(key).substring(0, 12);
626	    }
627	
628	    /**
629	     * Rejects a create whose computed {@code householdId} (derived from {@code lastName} and
630	     * {@code postcode}, see {@link #householdIdFor}) already belongs to an existing owner, unless
631	     * the request opts in via {@code sharesHousehold}. Because the household is keyed on
632	     * {@code (lastName, postcode)}, a second owner sharing both is the same household: it is
633	     * rejected with a 409 as a household duplicate unless it declares {@code sharesHousehold}, in
634	     * which case it is created as a declared household member. The scan is taken over the existing
635	     * owners before this one is persisted.
636	     *
637	     * @param ownerFieldsDto the submitted owner fields ({@code lastName} and {@code postcode} set)
638	     * @throws DuplicateHouseholdException with a 409 status if the household already exists and the
639	     *                                     request did not opt in via {@code sharesHousehold}
640	     */
641	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
642	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
643	            return;
644	        }
645	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
646	        boolean duplicate = this.clinicService.findAllOwners().stream()
647	            .filter(existing -> !existing.isDeleted())
648	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
649	        if (duplicate) {
650	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
651	        }
652	    }
653	
654	    /**
655	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
656	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
657	     * after this create. Because {@code householdId} is derived from the owner's {@code lastName}
658	     * and {@code postcode} (see {@link #assignHouseholdId}), the count reflects every
659	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
660	     * The count is taken before this owner is persisted, so it is one more than the number of
661	     * existing household members.
662	     *
663	     * @param owner the owner being created (with its {@code householdId} already assigned)
664	     */
665	    private void assignHouseholdMemberCount(Owner owner) {
666	        String householdId = owner.getHouseholdId();
667	        long existing = this.clinicService.findAllOwners().stream()
668	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
669	            .count();
670	        owner.setHouseholdMemberCount((int) (existing + 1));
671	    }
672	
673	    /**
674	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
675	     * already share this owner's {@code firstName} and {@code lastName}, compared
676	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
677	     * pre-existing namesakes.
678	     *
679	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
680	     */
681	    private void assignNamesakeCount(Owner owner) {
682	        String firstName = owner.getFirstName();
683	        String lastName = owner.getLastName();
684	        long count = this.clinicService.findAllOwners().stream()
685	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
686	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
687	            .count();
688	        owner.setNamesakeCount((int) count);
689	    }
690	
691	    /**
692	     * Assigns the owner's {@code membershipNumber} on create, formatted
693	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
694	     * code and YY is the last two digits of the {@code registrationDate}'s fiscal year (which
695	     * starts on 1 July), zero-padded (e.g. {@code 'NSW-A1B2C3D4-M27'}). The YY segment therefore
696	     * matches the owner's {@code fiscalYear}. Derived purely from the owner's own fields, so both
697	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
698	     *
699	     * @param owner the owner being created (with its {@code customerCode} and
700	     *              {@code registrationDate} already set)
701	     */
702	    private void assignMembershipNumber(Owner owner) {
703	        String yy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
704	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
705	    }
706	
707	    /**
708	     * The number of owners that must already carry a registration date before a subsequent
709	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
710	     * once the count of owners already registered on that day <em>exceeds</em> this value.
711	     */
712	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
713	
714	    /**
715	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
716	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
717	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
718	     * existing owners before this one is persisted, so it reflects only the owners already
719	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
720	     *
721	     * @param owner the owner being created (with its {@code registrationDate} already set)
722	     */
723	    private void assignBulkSignupWarning(Owner owner) {
724	        LocalDate registrationDate = owner.getRegistrationDate();
725	        long count = this.clinicService.findAllOwners().stream()
726	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
727	            .count();
728	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
729	    }
730	
731	    /**
732	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
733	     * {@link #rejectDuplicateIdentity} and {@link #rejectDuplicateHousehold}, so this owner is not
734	     * a hard duplicate. A declared household member (one that opted in via {@code sharesHousehold})
735	     * is never flagged: it is an acknowledged member of the household, not a suspected duplicate,
736	     * so {@code possibleDuplicate} is {@code false}. Otherwise it is a <em>possible</em> duplicate
737	     * when an existing owner shares its {@code lastName} (compared case-insensitively) and its
738	     * {@code postcode} but has a <em>different</em> normalized {@code telephone}:
739	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to that owner's
740	     * id (the earliest such owner by id when several match). Otherwise {@code possibleDuplicate} is
741	     * {@code false} and {@code possibleDuplicateOf} is left unset. The scan is taken over the
742	     * existing owners before this one is persisted.
743	     *
744	     * @param owner the owner being created (with its {@code lastName}, {@code postcode} and
745	     *              already-normalized {@code telephone} set)
746	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
747	     */
748	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
749	        if (declaredHouseholdMember) {
750	            owner.setPossibleDuplicate(false);
751	            owner.setPossibleDuplicateOf(null);
752	            return;
753	        }
754	        String lastName = owner.getLastName();
755	        String postcode = owner.getPostcode();
756	        String telephone = owner.getTelephone();
757	        Integer matchId = null;
758	        if (lastName != null && postcode != null && telephone != null) {
759	            matchId = this.clinicService.findAllOwners().stream()
760	                .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
761	                .filter(existing -> postcode.equals(existing.getPostcode()))
762	                .filter(existing -> !telephone.equals(existing.getTelephone()))
763	                .map(Owner::getId)
764	                .filter(id -> id != null)
765	                .min(Integer::compareTo)
766	                .orElse(null);
767	        }
768	        owner.setPossibleDuplicate(matchId != null);
769	        owner.setPossibleDuplicateOf(matchId);
770	    }
771	
772	    /**
773	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
774	     *
775	     * @param value the string to hash
776	     * @return the 64-character lower-case hex digest
777	     */
778	    private static String sha256Hex(String value) {
779	        try {
780	            byte[] digest = MessageDigest.getInstance("SHA-256")
781	                .digest(value.getBytes(StandardCharsets.UTF_8));
782	            StringBuilder sb = new StringBuilder(digest.length * 2);
783	            for (byte b : digest) {
784	                sb.append(String.format("%02x", b));
785	            }
786	            return sb.toString();
787	        }
788	        catch (NoSuchAlgorithmException e) {
789	            throw new IllegalStateException("SHA-256 not available", e);
790	        }
791	    }
792	
793	    /**
794	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
795	     * owner. This single key consolidates what used to be three separate duplicate checks
796	     * (telephone, email and household): the key is
797	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
798	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
799	     * matches an existing owner's. Because the telephone is part of the key, two members of the
800	     * same household (same {@code householdId}) with different telephones have different identity
801	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
802	     * and email have already been normalized by {@link #normalizeTelephone} and
803	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
804	     * input formats collapse to the same value.
805	     *
806	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
807	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
808	     *                                    whole identity key
809	     */
810	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
811	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(),
812	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
813	        boolean duplicate = this.clinicService.findAllOwners().stream()
814	            .filter(owner -> !owner.isDeleted())
815	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getPostcode(),
816	                owner.getTelephone(), owner.getEmail()))
817	            .anyMatch(identityKey::equals);
818	        if (duplicate) {
819	            throw new DuplicateIdentityException(identityKey);
820	        }
821	    }
822	
823	    /**
824	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
825	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
826	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
827	     * absent), and the {@code householdId} is derived from the {@code lastName} and
828	     * {@code postcode} the same way {@link #assignHouseholdId} assigns it (see
829	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
830	     * their whole identities match, regardless of the exact input formats.
831	     *
832	     * @param lastName  the owner's last name
833	     * @param postcode  the owner's postcode
834	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
835	     * @param email     the owner's email, possibly {@code null}
836	     * @return the canonical identity key
837	     */
838	    private static String identityKeyFor(String lastName, String postcode, String telephone, String email) {
839	        String normalizedTelephone = toE164(telephone);
840	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
841	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
842	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, postcode);
843	    }
844	
845	    /**
846	     * The maximum number of owners permitted in a single city. A create is rejected once the
847	     * owner's city already contains this many owners.
848	     */
849	    private static final long CITY_CAPACITY = 50;
850	
851	    /**
852	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
853	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
854	     * before this owner is persisted.
855	     *
856	     * @param city the submitted city
857	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
858	     */
859	    private void rejectCityAtCapacity(String city) {
860	        long count = this.clinicService.findAllOwners().stream()
861	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
862	            .count();
863	        if (count >= CITY_CAPACITY) {
864	            throw new CityAtCapacityException(city);
865	        }
866	    }
867	
868	    /**
869	     * The maximum number of owners permitted to be created in a single day. A create is
870	     * rejected once this many owners already carry today's {@code registrationDate}.
871	     */
872	    private static final long DAILY_LIMIT = 100;
873	
874	    /**
875	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
876	     * business day as their {@code registrationDate}. The day counted against is this create's
877	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
878	     * so owners are counted per adjusted business day. The count is taken before this owner is
879	     * persisted.
880	     *
881	     * @param businessDay the effective, business-day-adjusted registration date of this create
882	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
883	     */
884	    private void rejectDailyLimit(LocalDate businessDay) {
885	        long count = this.clinicService.findAllOwners().stream()
886	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
887	            .count();
888	        if (count >= DAILY_LIMIT) {
889	            throw new DailyOwnerLimitExceededException(businessDay);
890	        }
891	    }
892	
893	    /**
894	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
895	     * every internal run of whitespace is collapsed to a single space, and the result is
896	     * lower-cased. A {@code null} value collapses to the empty string.
897	     *
898	     * @param value the value to canonicalize, possibly {@code null}
899	     * @return the collapsed, lower-cased value
900	     */
901	    private static String collapse(String value) {
902	        if (value == null) {
903	            return "";
904	        }
905	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
906	    }
907	
908	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
909	    @Override
910	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
911	        Owner owner = this.clinicService.findOwnerById(ownerId);
912	        if (owner != null) {
913	            Pet pet = owner.getPet(petId);
914	            if (pet != null) {
915	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
916	            }
917	        }
918	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
919	    }
920	}
